-- Story sentences
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (1, 1, 0, 'It was a beautiful sunny morning.', '那是一个阳光明媚的早晨。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (2, 1, 1, 'I decided to go to the beach with my friends.', '我决定和朋友一起去海滩。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (3, 1, 2, 'The sea was calm and the water was crystal clear.', '海面平静，海水清澈见底。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (4, 1, 3, 'We played volleyball and built sandcastles.', '我们打排球，堆沙堡。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (5, 1, 4, 'At noon, we had a delicious picnic lunch.', '中午，我们吃了一顿美味的野餐午餐。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (6, 1, 5, 'After lunch, we went for a long walk along the shore.', '午饭后，我们沿着海岸走了很长一段路。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (7, 1, 6, 'The sunset was absolutely breathtaking.', '日落真是美得令人惊叹。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (8, 1, 7, 'It was a perfect day that I will never forget.', '那是我永远不会忘记的完美一天。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (9, 2, 0, 'I was sitting in a coffee shop, reading a book.', '我坐在咖啡店里，看书。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (10, 2, 1, 'A girl came over and asked if the seat was taken.', '一个女孩走过来问这个座位是否有人。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (11, 2, 2, 'I smiled and told her she could sit down.', '我微笑着告诉她可以坐下。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (12, 2, 3, 'We started talking about our favorite books.', '我们开始谈论我们最喜欢的书。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (13, 2, 4, 'Her name was Emily, and she was a writer.', '她的名字叫Emily，她是一名作家。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (14, 2, 5, 'We exchanged phone numbers and promised to meet again.', '我们交换了电话号码，并承诺会再见面。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (15, 2, 6, 'Now she is one of my best friends.', '现在她是我最好的朋友之一。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (16, 2, 7, 'Sometimes the best friendships start from simple moments.', '有时候最好的友谊始于简单的瞬间。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (17, 3, 0, 'I had an important job interview last Monday.', '上周一我有一个重要的工作面试。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (18, 3, 1, 'I arrived ten minutes early to the company.', '我提前十分钟到达公司。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (19, 3, 2, 'The receptionist was very friendly and professional.', '前台接待非常友好和专业。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (20, 3, 3, 'I was taken to a conference room where three interviewers waited.', '我被带到一间会议室，三位面试官在等着。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (21, 3, 4, 'They asked me about my previous work experience.', '他们问我之前的工作经历。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (22, 3, 5, 'I gave clear and confident answers to all their questions.', '我对他们所有的问题都给出了清晰而自信的回答。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (23, 3, 6, 'At the end of the interview, they showed me around the office.', '面试结束时，他们带我参观了办公室。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (24, 3, 7, 'I felt positive about the interview and hopeful about getting the job.', '我对面试感到很积极，对获得这份工作充满希望。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (25, 3, 8, 'Three days later, I received an offer letter by email.', '三天后，我通过电子邮件收到了录用通知。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (26, 4, 0, 'Learning a new language has always been a dream of mine.', '学习一门新语言一直是我的梦想。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (27, 4, 1, 'I decided to start learning Japanese six months ago.', '六个月前我决定开始学日语。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (28, 4, 2, 'At first, it was very challenging to memorize the characters.', '起初，记忆汉字非常具有挑战性。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (29, 4, 3, 'I spent at least one hour every day practicing.', '我每天至少花一个小时练习。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (30, 4, 4, 'I used language apps and watched Japanese movies with subtitles.', '我使用语言应用程序，看带字幕的日本电影。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (31, 4, 5, 'Slowly but surely, I began to understand more and more.', '缓慢但肯定地，我开始理解得越来越多。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (32, 4, 6, 'Last month, I traveled to Tokyo and was able to communicate in Japanese.', '上个月，我去东京旅行，能够用日语交流了。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (33, 4, 7, 'The locals were surprised and delighted by my efforts.', '当地人对我的努力感到惊讶和高兴。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (34, 4, 8, 'Learning a language opens doors to new cultures and friendships.', '学习一门语言打开了通往新文化和友谊的大门。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (35, 5, 0, 'Last summer, I embarked on a two-week adventure to Paris.', '去年夏天，我开始了为期两周的巴黎冒险。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (36, 5, 1, 'The moment I stepped out of the train station, I fell in love with the city.', '当我走出火车站的那一刻，我就爱上了这座城市。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (37, 5, 2, 'Paris, the City of Light, was even more magnificent than I had imagined.', '巴黎，这座光之城，比我想象的还要壮丽。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (38, 5, 3, 'I visited the iconic Eiffel Tower on my first evening.', '我在第一天晚上参观了标志性的埃菲尔铁塔。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (39, 5, 4, 'The panoramic view from the top was absolutely stunning.', '从顶部看到的全景令人惊叹。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (40, 5, 5, 'I spent hours exploring the world-famous Louvre Museum.', '我花了几个小时探索世界著名的卢浮宫博物馆。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (41, 5, 6, 'Standing in front of the Mona Lisa, I felt a deep sense of awe.', '站在《蒙娜丽莎》面前，我感到深深的敬畏。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (42, 5, 7, 'I wandered through the charming streets of Montmartre and enjoyed fresh croissants.', '我漫步在蒙马特迷人的街道上，享用新鲜的羊角面包。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (43, 5, 8, 'Each morning, I would sit at a café and watch the world go by.', '每天早上，我会坐在咖啡馆里，看着世界从我身边流过。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (44, 5, 9, 'On my last day, I took a scenic cruise along the Seine River.', '在最后一天，我沿着塞纳河进行了一次风景优美的巡航。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (45, 5, 10, 'Paris has a way of capturing your heart and never letting go.', '巴黎有一种抓住你的心并永不放手的方式。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (46, 5, 11, 'I left with countless memories and a promise to return soon.', '我带着无数的回忆和很快回来的承诺离开了。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (47, 6, 0, 'The morning sun was shining brightly.', '早晨的阳光明媚地照耀着。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (48, 6, 1, 'I had many things to do today.', '我今天有很多事情要做。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (49, 6, 2, 'It was a typical afternoon in my daily life.', '这是我日常生活中典型的day。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (50, 6, 3, 'I had many things to do today.', '我今天有很多事情要做。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (51, 6, 4, 'It was a typical evening in my daily life.', '这是我日常生活中典型的morning。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (52, 6, 5, 'My family members were supportive and helpful.', '我的家人很支持和乐于助人。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (53, 6, 6, 'The weather was perfect for what I needed to do.', '天气非常适合我需要做的事情。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (54, 6, 7, 'I learned something new from this experience.', '我从这次经历中学到了新东西。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (55, 6, 8, 'I took a short break to relax my mind.', '我短暂休息了一下，放松心情。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (56, 6, 9, 'The process was more enjoyable than I expected.', '过程比我想象的更有趣。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (57, 6, 10, 'I learned something new from this experience.', '我从这次经历中学到了新东西。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (58, 6, 11, 'I carefully planned my schedule for the day.', '我仔细计划了今天的时间表。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (59, 6, 12, 'The task seemed simple but required attention.', '任务看似简单，但需要注意力。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (60, 6, 13, 'I took a short break to relax my mind.', '我短暂休息了一下，放松心情。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (61, 6, 14, 'I learned something new from this experience.', '我从这次经历中学到了新东西。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (62, 6, 15, 'My family members were supportive and helpful.', '我的家人很支持和乐于助人。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (63, 6, 16, 'I felt a sense of accomplishment.', '我感到一种成就感。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (64, 6, 17, 'Time passed quickly as I focused on my work.', '当我专注于工作时，时间过得很快。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (65, 6, 18, 'The process was more enjoyable than I expected.', '过程比我想象的更有趣。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (66, 6, 19, 'I looked forward to tomorrow with hope.', '我充满希望地期待着明天。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (67, 6, 20, 'I looked forward to tomorrow with hope.', '我充满希望地期待着明天。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (68, 6, 21, 'This day taught me valuable lessons.', '这一天教会了我宝贵的经验。', '');
INSERT OR IGNORE INTO story_sentences (id, story_id, sentence_index, english, chinese, audio_file) VALUES (69, 7, 0, 'It was a typical week in my daily life.', '这是我日常生活中典型的day。', '');
